// Stable ids (hash of the English text) so "recently asked" survives bank edits.
export function qid(kind, en) { let h = 2166136261; const s = kind + en; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return kind + (h >>> 0).toString(36); }
